#!/usr/bin/env node
// Copyright (C) 2026 Alexandre Demartin
//
// `npm run bench:types:large`: the check time and memory of bench/large/'s cases on a large synthetic schema, for pgcast
// and for Zapatos 6.6.1 in the same run, against bench/large/baseline.json. bench:types counts Instantiations on the
// fixture's 17 tables, which cannot see a generic column related to a union of 1,600 names: +20 % check time at +0.9 %
// Instantiations (#918).
//
// - The schema: 280 tables and 20 views of invented names, created in a database of its own on TEST_DATABASE_URL's
//   server and generated by each library's own codegen, so each is checked against what it writes. Nothing large is
//   committed. Zapatos 6.6.1 is fetched once into node_modules/.cache/pgcast-zapatos-661, never a dependency.
// - Each case is one file of bench/large/, checked alone; `libCheck` checks the generic ones with skipLibCheck: false.
// - Each case runs `--runs` times (5 by default) per library, the libraries alternated and the order reversed each run.
// - The gate: per case, pgcast's median over Zapatos's, for check time and for memory, against the baseline's ratio.
//   Both libraries run on the same machine, so the ratio holds across machines where a time does not. Fails above
//   +`threshold` or below -`threshold` (a gain then needs `--update`, so that the baseline follows it).
import {spawnSync} from 'node:child_process';
import {existsSync, readFileSync, rmSync, statSync, writeFileSync} from 'node:fs';
import {createRequire} from 'node:module';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';

const
  root = fileURLToPath(new URL('..', import.meta.url)),
  require = createRequire(import.meta.url),
  tscPath = require.resolve('typescript/bin/tsc'),
  tsVersion = require('typescript/package.json').version,
  baselineName = 'bench/large/baseline.json',
  baselinePath = join(root, baselineName),
  threshold = 0.2,
  zapatosVersion = '6.6.1',
  zapatosCache = join(root, 'node_modules/.cache/pgcast-zapatos-661'),
  zapatosRoot = join(zapatosCache, 'node_modules/zapatos'),
  work = join(root, 'node_modules/.cache/pgcast-bench-large'),
  args = process.argv.slice(2),
  option = name => args.includes(name) ? args[args.indexOf(name) + 1] : undefined,
  runs = Number(option('--runs') ?? 5),
  update = args.includes('--update'),
  aliases = args.includes('--aliases');

function fail(...lines) {
  for (const line of lines) console.error(line);
  process.exit(1);
}

// `--aliases`: pgcast's output with valuesTypedAsAliases as well, measured beside the default, outside the gate (#921)
const libraries = {
  pgcast: {generate: join(root, 'dist/generate'), db: join(root, 'dist/db')},
  ...aliases && {aliases: {generate: join(root, 'dist/generate'), db: join(root, 'dist/db'), config: {valuesTypedAsAliases: true}}},
  zapatos: {generate: join(zapatosRoot, 'dist/generate'), db: join(zapatosRoot, 'dist/db')},
};

const allCases = {
  parentOf: {files: ['parentOf.ts'], skipLibCheck: true},
  lateralFor: {files: ['lateralFor.ts'], skipLibCheck: true},
  selectWith: {files: ['selectWith.ts'], skipLibCheck: true},
  libCheck: {files: ['parentOf.ts', 'lateralFor.ts', 'selectWith.ts'], skipLibCheck: false},
};
// `--cases parentOf,lateralFor`: a CI job runs some of them
const cases = Object.fromEntries((option('--cases')?.split(',') ?? Object.keys(allCases)).map(name =>
  [name, Object.hasOwn(allCases, name) ? allCases[name] : fail(`bench:types:large: no case ${name}; the cases are ${Object.keys(allCases).join(', ')}.`)]));

function run(command, commandArgs) {
  const result = spawnSync(command, commandArgs, {cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024});
  if (result.status !== 0) fail(result.stdout + result.stderr, `bench:types:large: ${command} ${commandArgs.join(' ')} failed`);
  return result.stdout;
}

if (!Number.isSafeInteger(runs) || runs < 1) fail('bench:types:large: --runs takes a whole number of runs, 1 or more.');

/* === the synthetic schema === */

// a neutral domain of invented words: 14 × 20 tables, 50 × 34 column names
const
  areas = ['depot', 'route', 'parcel', 'survey', 'harvest', 'garden', 'orchard', 'mill', 'kiln', 'loom', 'quarry',
    'harbour', 'ledger', 'archive'],
  things = ['batch', 'entry', 'note', 'tally', 'slot', 'record', 'shift', 'crate', 'tag', 'check', 'visit', 'ticket',
    'rota', 'log', 'item', 'plan', 'stock', 'yield', 'grade', 'sample'],
  prefixes = ['amber', 'birch', 'cedar', 'delta', 'ember', 'fjord', 'grove', 'heath', 'iris', 'juniper', 'kestrel',
    'lark', 'maple', 'nectar', 'opal', 'pine', 'quill', 'reed', 'sable', 'thorn', 'umber', 'vale', 'willow', 'yarrow',
    'zephyr', 'aspen', 'brook', 'cliff', 'dune', 'elm', 'fern', 'glen', 'hazel', 'ivy', 'jade', 'kelp', 'lichen', 'moss',
    'north', 'oak', 'pebble', 'quartz', 'ridge', 'sage', 'tide', 'upland', 'vine', 'wren', 'yew', 'zinc'],
  suffixes = ['code', 'label', 'weight', 'height', 'width', 'depth', 'count', 'total', 'price', 'cost', 'rate', 'score',
    'level', 'rank', 'colour', 'shape', 'size', 'origin', 'source', 'target', 'start', 'finish', 'due', 'opened',
    'closed', 'checked', 'limit', 'margin', 'offset', 'ratio', 'share', 'quota', 'budget', 'mark'],
  columnPool = prefixes.flatMap(prefix => suffixes.map(suffix => `${prefix}_${suffix}`)),
  columnTypes = ['integer', 'text', 'boolean', 'timestamptz', 'numeric', 'jsonb', 'date', 'bigint', 'text[]', 'real',
    'uuid', 'stage'],
  columnsPerTable = 12,
  tables = areas.flatMap(area => things.map(thing => `${area}_${thing}`)),
  views = tables.slice(0, 20).map(table => `${table}_summary`);

// every pool name appears at least once: table i takes names i × 12 to i × 12 + 11, round the pool
const schemaSQL = [
  `CREATE TYPE stage AS ENUM ('draft', 'open', 'closed', 'archived');`,
  ...tables.map((table, i) => `CREATE TABLE ${table} (\n  ` + [
    'id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY',
    'name text NOT NULL',
    'notes text',
    `stage stage NOT NULL DEFAULT 'draft'`,
    'created_at timestamptz NOT NULL DEFAULT now()',
    'updated_at timestamptz',
    ...Array.from({length: columnsPerTable}, (_, j) => {
      const n = i * columnsPerTable + j;
      return `${columnPool[n % columnPool.length]} ${columnTypes[n % columnTypes.length]}${n % 3 ? '' : ' NOT NULL'}`;
    }),
  ].join(',\n  ') + '\n);'),
  ...views.map((view, i) => `CREATE VIEW ${view} AS SELECT id, name, stage, created_at FROM ${tables[i]};`),
].join('\n');

/* === Zapatos 6.6.1 and the generated schemas === */

const installedZapatos = () => {
  try { return JSON.parse(readFileSync(join(zapatosRoot, 'package.json'), 'utf8')).version; }
  catch { return undefined; }
};
if (installedZapatos() !== zapatosVersion) {
  rmSync(zapatosCache, {recursive: true, force: true});
  // its peers (pg, @types/pg, typescript) are the root's, as pgcast's are
  run('npm', ['install', '--prefix', zapatosCache, '--no-save', '--no-package-lock', '--ignore-scripts', '--no-audit',
    '--no-fund', '--legacy-peer-deps', `zapatos@${zapatosVersion}`]);
}

// pgcast's codegen and declarations as this checkout builds them
run(process.execPath, [tscPath]);

const envFile = join(root, 'src/.env');
if (existsSync(envFile)) process.loadEnvFile(envFile);  // the environment wins
if (!process.env.TEST_DATABASE_URL) {
  fail('bench:types:large: TEST_DATABASE_URL is not set: set it in src/.env or in the environment (AGENTS.md § Local environment).');
}

const pg = require('pg');
const database = `pgcast_test_${process.pid}_bench_large`;  // dropped by any `npm test` once this process is gone
const urlFor = name => {
  const url = new URL(process.env.TEST_DATABASE_URL);
  url.pathname = '/' + name;
  return url.toString();
};
const withClient = async (url, fn) => {
  const client = new pg.Client({connectionString: url});
  client.on('error', () => {});  // a DROP DATABASE ... WITH (FORCE) elsewhere ends it: the query in progress rejects
  await client.connect();
  try { return await fn(client); } finally { await client.end(); }
};

rmSync(work, {recursive: true, force: true});
const admin = process.env.TEST_DATABASE_URL;
await withClient(admin, client => client.query(`CREATE DATABASE ${database}`));
try {
  await withClient(urlFor(database), client => client.query(schemaSQL));
  for (const [name, library] of Object.entries(libraries)) {
    await require(library.generate).generate({
      db: {connectionString: urlFor(database)}, outDir: join(work, name), progressListener: false, warningListener: false,
      ...library.config,
    });
    console.log(`${name}: schema.d.ts ${statSync(join(work, name, 'zapatos/schema.d.ts')).size} bytes`);
  }
} finally {
  await withClient(admin, client => client.query(`DROP DATABASE IF EXISTS ${database} WITH (FORCE)`));
}

/* === the runs === */

const projectFor = (library, name) => {
  const path = join(work, library, `tsconfig.${name}.json`);
  writeFileSync(path, JSON.stringify({
    extends: join(root, 'bench/large/tsconfig.json'),
    files: cases[name].files.map(file => join(root, 'bench/large', file)),
    include: [join(work, library, 'zapatos/**/*')],
    compilerOptions: {skipLibCheck: cases[name].skipLibCheck, paths: {'zapatos/db': [libraries[library].db]}},
  }, null, 2));
  return path;
};

const measure = project => {
  const
    output = run(process.execPath, [tscPath, '-p', project, '--extendedDiagnostics']),
    figures = Object.fromEntries([...output.matchAll(/^([A-Za-z ]+):\s+(\S+)$/gm)].map(([, key, value]) => [key, value])),
    time = Number(/^([\d.]+)s$/.exec(figures['Check time'] ?? '')?.[1]),
    memory = Number(/^(\d+)K$/.exec(figures['Memory used'] ?? '')?.[1]);
  if (!Number.isFinite(time) || !Number.isFinite(memory)) fail(output, `bench:types:large: no Check time or Memory used in tsc -p ${project}`);
  return {time, memory};
};

const median = values => {
  const sorted = [...values].sort((a, b) => a - b), mid = sorted.length >> 1;
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const
  projects = Object.fromEntries(Object.keys(cases).map(name =>
    [name, Object.fromEntries(Object.keys(libraries).map(library => [library, projectFor(library, name)]))])),
  samples = Object.fromEntries(Object.keys(cases).map(name =>
    [name, Object.fromEntries(Object.keys(libraries).map(library => [library, []]))]));

// each run printed, so that the noise between runs can be read from a CI log
for (let i = 0; i < runs; i++) {
  const order = i % 2 ? Object.keys(libraries).reverse() : Object.keys(libraries);
  for (const name of Object.keys(cases)) {
    for (const library of order) {
      const result = measure(projects[name][library]);
      samples[name][library].push(result);
      console.log(`run ${i + 1} of ${runs}: ${name} ${library} ${result.time} s ${result.memory}K`);
    }
  }
}

const current = Object.fromEntries(Object.entries(samples).map(([name, byLibrary]) => {
  const medians = Object.fromEntries(Object.entries(byLibrary).map(([library, results]) => [library, {
    time: median(results.map(r => r.time)), memory: median(results.map(r => r.memory)),
  }]));
  return [name, {
    ...medians,
    time: medians.pgcast.time / medians.zapatos.time,
    memory: medians.pgcast.memory / medians.zapatos.memory,
    spread: Object.fromEntries(Object.entries(byLibrary).map(([library, results]) => {
      const times = results.map(r => r.time);
      return [library, (Math.max(...times) - Math.min(...times)) / median(times)];
    })),
  }];
}));

/* === the report and the gate === */

const
  ratio = value => value.toFixed(2),
  seconds = value => `${value.toFixed(2)} s`,
  megabytes = value => `${Math.round(value / 1024)} MB`,
  percent = value => `${value >= 0 ? '+' : ''}${(value * 100).toFixed(1)} %`,
  baseline = !existsSync(baselinePath) ? undefined : JSON.parse(readFileSync(baselinePath, 'utf8')),
  rows = [['', 'pgcast', ...aliases ? ['aliases'] : [], 'Zapatos', 'ratio', 'baseline', 'change', 'spread (pgcast, Zapatos)']],
  outside = [];

for (const [name, figures] of Object.entries(current)) {
  for (const [key, show] of [['time', seconds], ['memory', megabytes]]) {
    const
      before = baseline?.cases?.[name]?.[key],
      change = before === undefined ? undefined : figures[key] / before - 1;
    if (change !== undefined && Math.abs(change) > threshold) outside.push(`${name} ${key} ${percent(change)}`);
    rows.push([`${name} ${key === 'time' ? 'check time' : 'memory'}`, show(figures.pgcast[key]),
      ...aliases ? [show(figures.aliases[key])] : [], show(figures.zapatos[key]),
      ratio(figures[key]), before === undefined ? '' : ratio(before), change === undefined ? '' : percent(change),
      key === 'time' ? `${percent(figures.spread.pgcast)}, ${percent(figures.spread.zapatos)}` : '']);
  }
}

console.log(`\nMedians of ${runs} runs, TypeScript ${tsVersion}, ${tables.length} tables, ${views.length} views, ` +
  `${new Set([...columnPool, 'id', 'name', 'notes', 'stage', 'created_at', 'updated_at']).size} column names:\n`);
const widths = rows[0].map((_, i) => Math.max(...rows.map(row => String(row[i]).length)));
for (const row of rows) console.log(row.map((cell, i) => String(cell)[i ? 'padStart' : 'padEnd'](widths[i])).join('  '));

if (update) {
  // the cases not run keep their ratios
  const before = existsSync(baselinePath) ? JSON.parse(readFileSync(baselinePath, 'utf8')).cases : {};
  writeFileSync(baselinePath, JSON.stringify({
    typescript: tsVersion, zapatos: zapatosVersion,
    cases: Object.fromEntries(Object.keys(allCases).flatMap(name => name in current ?
      [[name, {time: Number(current[name].time.toFixed(3)), memory: Number(current[name].memory.toFixed(3))}]] :
      name in before ? [[name, before[name]]] : [])),
  }, null, 2) + '\n');
  console.log(`\nbench:types:large: ${baselineName} updated`);
  process.exit(0);
}

if (!baseline) fail(`\nbench:types:large: no ${baselineName}: run \`npm run bench:types:large -- --update\` and commit it.`);
if (baseline.typescript !== tsVersion) {
  fail(`\nbench:types:large: ${baselineName} was measured with TypeScript ${baseline.typescript}, this is ${tsVersion}.`,
    'Run `npm run bench:types:large -- --update` and commit the new baseline.');
}
const missing = Object.keys(cases).filter(name => !['time', 'memory'].every(key => baseline.cases?.[name]?.[key] > 0));
if (missing.length) fail(`\nbench:types:large: ${baselineName} has no positive ratios for ${missing.join(', ')}.`);
if (outside.length) {
  fail(`\nbench:types:large: pgcast over Zapatos ${zapatosVersion} moved by more than ${threshold * 100} % ` +
    `from ${baselineName}: ${outside.join(', ')}.`,
  'A rise: find the type that costs more. A gain, or a justified rise: run `npm run bench:types:large -- --update`',
  'and give the figures in the PR (skill type-tests).');
}
